namespace Fanex.BetList.Age.BetListHTMLBuilderExt.WinLostBuilder
{
    using Fanex.BetList.Age.ExtTemplate;
    using Fanex.BetList.Core.Entities;
    using Fanex.BetList.Core.Utils;

    /// <summary>
    /// Build WinLoss column
    /// </summary>
    public class WinLost1 : IWinLoss
    {
        /// <summary>
        /// Gets or sets the template.
        /// </summary>
        /// <value>
        /// The template.
        /// </value>
        public WinLoss_Template Template { get; set; }

        /// <summary>
        /// Renders the specified ticket.
        /// </summary>
        /// <param name="ticket">The ticket.</param>
        /// <returns></returns>
        public WinLoss_Template Render(ITicket ticket)
        {
            if (ticket.Status.Equals(BetStatus.Running) || ticket.Status.Equals(BetStatus.Waiting))
            {
                Template.winloss = "-";
                Template.comm = string.Empty;
            }
            else
            {
                Template.winloss = ConvertByBetType.Winloss(ticket.Winlost);
                Template.comm = ConvertByBetType.Comm(ticket.PlayerComm);
            }

            return this.Template;
        }

        /// <summary>
        /// Renders the specified ticket for smartphone.
        /// </summary>
        /// <param name="ticket">The ticket.</param>
        /// <returns></returns>
        public WinLoss_Template RenderForSmartphone(ITicket ticket)
        {
            if (ticket.Status.Equals(BetStatus.Running) || ticket.Status.Equals(BetStatus.Waiting))
            {
                Template.winloss = "-";
                Template.comm = string.Empty;
            }
            else
            {
                Template.winloss = ConvertByBetType.Winloss(ticket.Winlost, Formatter.DECIMALFORMAT1);
                Template.comm = ConvertByBetType.Comm(ticket.PlayerComm, Formatter.DECIMALFORMAT1);
            }

            return this.Template;
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="WinLost1" /> class.
        /// </summary>
        public WinLost1()
        {
            this.Template = new WinLoss_Template();
        }
    }
}
